const restrictionHistory = `-- name: RestrictionHistory :many
SELECT id,restricted_at FROM app.live_account_restrictions WHERE account_id=$1 ORDER BY restricted_at,id LIMIT 100
`

type RestrictionHistoryRow struct {
	ID           string
	RestrictedAt pgtype.Timestamptz
}

func (q *Queries) RestrictionHistory(ctx context.Context, accountID string) ([]RestrictionHistoryRow, error) {
	rows, err := q.db.Query(ctx, restrictionHistory, accountID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []RestrictionHistoryRow{}
	for rows.Next() {
		var i RestrictionHistoryRow
		if err := rows.Scan(&i.ID, &i.RestrictedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

